using Mbb.Archive.Modules.AccessControl.Application;
using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.AccessControl.Application.Abstractions;using Mbb.Archive.Modules.AccessControl.Domain.Roles;namespace Mbb.Archive.Modules.AccessControl.Application.Roles;
public sealed class CreateRoleCommandHandler:ICommandHandler<CreateRoleCommand,Guid>{private readonly IAccessRepository _repo;private readonly IUnitOfWork<AccessControlBoundary> _uow;public CreateRoleCommandHandler(IAccessRepository r,IUnitOfWork<AccessControlBoundary> u){_repo=r;_uow=u;}public async Task<Result<Guid>> Handle(CreateRoleCommand c,CancellationToken ct){if(string.IsNullOrWhiteSpace(c.Code)||c.Code.Trim().Length>100||string.IsNullOrWhiteSpace(c.Name)||c.Name.Trim().Length>300)return Result<Guid>.Failure(Error.Validation("access.invalid_role","Rol kodu ve adı gereklidir; kod en fazla 100, ad 300 karakter olabilir."));if(await _repo.GetRoleByCodeAsync(c.Code.Trim(),ct) is not null)return Result<Guid>.Failure(Error.Conflict("access.role_exists","Role code already exists."));var role=Role.Create(c.Code,c.Name);await _repo.AddRoleAsync(role,ct);await _uow.SaveChangesAsync(ct);return Result<Guid>.Success(role.Id);}}
public sealed class GrantPermissionCommandHandler:ICommandHandler<GrantPermissionCommand>{private readonly IAccessRepository _repo;private readonly IUnitOfWork<AccessControlBoundary> _uow;public GrantPermissionCommandHandler(IAccessRepository r,IUnitOfWork<AccessControlBoundary> u){_repo=r;_uow=u;}public async Task<Result> Handle(GrantPermissionCommand c,CancellationToken ct){var role=await _repo.GetRoleAsync(c.RoleId,ct);if(role is null)return Result.Failure(Error.NotFound("access.role_not_found","Role not found."));role.Grant(c.Permission);await _uow.SaveChangesAsync(ct);return Result.Success();}}
public sealed class AssignRoleCommandHandler:ICommandHandler<AssignRoleCommand>{private readonly IAccessRepository _repo;private readonly IUnitOfWork<AccessControlBoundary> _uow;public AssignRoleCommandHandler(IAccessRepository r,IUnitOfWork<AccessControlBoundary> u){_repo=r;_uow=u;}public async Task<Result> Handle(AssignRoleCommand c,CancellationToken ct){if(await _repo.GetRoleAsync(c.RoleId,ct) is null)return Result.Failure(Error.NotFound("access.role_not_found","Role not found."));await _repo.AddUserRoleAsync(UserRole.Assign(c.SubjectId,c.RoleId),ct);await _uow.SaveChangesAsync(ct);return Result.Success();}}
